#include <iostream>
using namespace std;

enum class Size { SMALL, LARGE }; // constants always come first

int price(Size size) { // C++ enums don't carry fields directly, use a lookup instead
    switch (size) {
        case Size::SMALL: return 10;
        case Size::LARGE: return 20;
    }
    return 0;
}

int main() {
    cout << price(Size::SMALL) << endl;
    return 0;
}

