enum TrafficLight {
    RED(30), YELLOW(5), GREEN(25); // exactly three fixed constants, each with its own duration

    private final int durationSeconds;

    TrafficLight(int durationSeconds) { // enum constructors are implicitly private
        this.durationSeconds = durationSeconds;
    }

    public int getDurationSeconds() {
        return durationSeconds;
    }

    public TrafficLight next() {
        switch (this) {
            case RED: return GREEN;
            case GREEN: return YELLOW;
            case YELLOW: return RED;
            default: throw new IllegalStateException();
        }
    }
}

public class Main {
    public static void main(String[] args) {
        TrafficLight current = TrafficLight.RED;

        System.out.println(current + " lasts " + current.getDurationSeconds() + " seconds");
        current = current.next();
        System.out.println("Next: " + current);

        // values() returns every constant, in declaration order
        for (TrafficLight light : TrafficLight.values()) {
            System.out.println(light + " -> " + light.getDurationSeconds() + "s");
        }
    }
}

