from enum import Enum


class TrafficLight(Enum):
    RED = 30
    YELLOW = 5
    GREEN = 25  # exactly three fixed constants, each carrying its own duration

    @property
    def duration_seconds(self):
        return self.value

    def next(self):
        order = {
            TrafficLight.RED: TrafficLight.GREEN,
            TrafficLight.GREEN: TrafficLight.YELLOW,
            TrafficLight.YELLOW: TrafficLight.RED,
        }
        return order[self]


if __name__ == "__main__":
    current = TrafficLight.RED

    print(f"{current.name} lasts {current.duration_seconds} seconds")
    current = current.next()
    print(f"Next: {current.name}")

    # iterating an Enum class yields every constant, in declaration order
    for light in TrafficLight:
        print(f"{light.name} -> {light.duration_seconds}s")

codes.cpp:
#include <iostream>
using namespace std;

enum class TrafficLight { RED, YELLOW, GREEN }; // a fixed, type-safe set of constants

// C++ enums don't carry fields directly, duration lives in a lookup function instead
int durationSeconds(TrafficLight light) {
    switch (light) {
        case TrafficLight::RED: return 30;
        case TrafficLight::YELLOW: return 5;
        case TrafficLight::GREEN: return 25;
    }
    return 0;
}

TrafficLight next(TrafficLight light) {
    switch (light) {
        case TrafficLight::RED: return TrafficLight::GREEN;
        case TrafficLight::GREEN: return TrafficLight::YELLOW;
        case TrafficLight::YELLOW: return TrafficLight::RED;
    }
    return TrafficLight::RED;
}

string name(TrafficLight light) {
    switch (light) {
        case TrafficLight::RED: return "RED";
        case TrafficLight::YELLOW: return "YELLOW";
        case TrafficLight::GREEN: return "GREEN";
    }
    return "";
}

int main() {
    TrafficLight current = TrafficLight::RED;

    cout << name(current) << " lasts " << durationSeconds(current) << " seconds" << endl;
    current = next(current);
    cout << "Next: " << name(current) << endl;

    TrafficLight all[] = { TrafficLight::RED, TrafficLight::YELLOW, TrafficLight::GREEN };
    for (TrafficLight light : all) {
        cout << name(light) << " -> " << durationSeconds(light) << "s" << endl;
    }

    return 0;
}
